// 📎 Cấu hình multer: lưu file vào thư mục uploads/ với tên ngẫu nhiên (giữ đúng phần đuôi file)
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, path.join(process.cwd(), 'uploads'));
